import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { AlertController, NavController } from '@ionic/angular';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-experiment-dashboard',
  templateUrl: './experiment-dashboard.page.html',
  styleUrls: ['./experiment-dashboard.page.scss'],
})
export class ExperimentDashboardPage implements OnInit {
  sessionEmisUsertype: any;

  constructor(public navCtrl: NavController,public alertCtrl:AlertController,
    private alertController: AlertController, 
    private router: Router,private usersessionService: UserSessionService) {
    this.sessionEmisUsertype = this.usersessionService.emis_usertype();
     }

  ngOnInit() {
  }

  experimentsphase1() {
    this.router.navigate(['/tabs/domain'], { queryParams: { "name": "experiments"} }); 
  }

  experimentsphase2() {
    this.router.navigate(['/tabs/experiment-phase'], { queryParams: { "name": "experiments"} }); 
  }

  navigateBack() {
    this.router.navigate(['/tabs/stem-dashboard']);
  }

}
